import org.joget.apps.form.model.Element;
import org.joget.apps.form.model.FormData;
import org.joget.apps.form.service.FormUtil;

public boolean validate(Element element, FormData formData, String[] values) {
    boolean result = true;

    // Retrieve the selected choice value
    String choix = values[0];

    // Resolve the value for the available places (using FormUtil for dynamic form data resolution)
        String places = "#form.quotas.quota[{form.inscription_ecole.formation};{form.inscription_ecole.id_etablissement}]#";

    // Validation logic
    if ("Accepter".equals(choix) && "0".equals(places)) {
        result = false;
        // Get the element parameter name to identify the field
        String id = FormUtil.getElementParameterName(element);
        // Add an error message to the formData object
    formData.addFormError(id, "Il n'y a pas encore de places disponibles !");
    }

    return result; // Return the validation result
}

return validate(element, formData, values);
